CREATE OR REPLACE FUNCTION public.feya_commerce_set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.feya_fn_approve_execution_request_v1(p_execution_request_id uuid, p_expected_status text, p_human_user_id uuid, p_approval_reason text)
 RETURNS TABLE(execution_request_id uuid, request_status text, approval_hash text, approved_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_row public.feya_growth_execution_requests_v1%rowtype;
  v_now timestamptz := now();
begin
  if p_human_user_id is null then
    raise exception 'Human user id is required for execution approval';
  end if;

  if nullif(btrim(coalesce(p_approval_reason,'')),'') is null then
    raise exception 'Approval reason is required';
  end if;

  select *
    into v_row
  from public.feya_growth_execution_requests_v1 e
  where e.execution_request_id=p_execution_request_id
  for update;

  if not found then
    raise exception 'Execution request not found: %',p_execution_request_id;
  end if;

  if v_row.request_status <> p_expected_status then
    raise exception 'Stale execution request status: expected %, current %',
      p_expected_status,v_row.request_status;
  end if;

  if v_row.request_status <> 'APPROVAL_REQUIRED' then
    raise exception 'Execution request status % does not require approval',v_row.request_status;
  end if;

  update public.feya_growth_execution_requests_v1 e
  set request_status='APPROVED',
      approval_hash=v_row.request_hash,
      approved_by_user_id=p_human_user_id,
      approval_reason=p_approval_reason,
      approved_at=v_now,
      updated_at=v_now
  where e.execution_request_id=p_execution_request_id;

  return query
  select p_execution_request_id,'APPROVED'::text,v_row.request_hash,v_now;
end;
$function$

CREATE OR REPLACE FUNCTION public.feya_fn_create_execution_request_v1(p_action_code text, p_mutation_domain text, p_target_scope_json jsonb, p_target_version_refs_json jsonb, p_request_payload_json jsonb, p_rollback_plan_json jsonb, p_postflight_check_json jsonb, p_requested_by_type text, p_requested_by_user_id uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text)
 RETURNS TABLE(execution_request_id uuid, request_code text, created_new boolean, request_status text, request_hash text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_action public.feya_growth_registry_items_v1%rowtype;
  v_existing public.feya_growth_execution_requests_v1%rowtype;
  v_row public.feya_growth_execution_requests_v1%rowtype;
  v_code text;
  v_status text;
  v_requires_material_guard boolean := false;
  v_dry_run boolean := false;
  v_material jsonb;
  v_hash text;
begin
  if p_requested_by_type not in ('human','agent','system') then
    raise exception 'Unsupported requester type: %',p_requested_by_type;
  end if;

  if nullif(btrim(coalesce(p_action_code,'')),'') is null then
    raise exception 'Action code is required';
  end if;

  select *
    into v_action
  from public.feya_growth_registry_items_v1 r
  where r.registry_type='action_capability'
    and r.item_code=p_action_code
    and r.active_flag=true
  order by r.version_no desc
  limit 1;

  if not found then
    raise exception 'Active Action Capability not found: %',p_action_code;
  end if;

  if v_action.item_state='UNAVAILABLE' then
    raise exception 'Action Capability % is unavailable',p_action_code;
  end if;

  v_requires_material_guard :=
    coalesce((v_action.config_json ->> 'production_mutation')::boolean,false)
    or coalesce((v_action.config_json ->> 'canonical_seo_mutation')::boolean,false)
    or coalesce((v_action.config_json ->> 'security_mutation')::boolean,false)
    or coalesce((v_action.config_json ->> 'indexation_mutation')::boolean,false);

  v_dry_run := coalesce(
    nullif(p_request_payload_json ->> 'dry_run','')::boolean,
    nullif(p_request_payload_json ->> 'dryRun','')::boolean,
    false
  );

  if v_requires_material_guard then
    if nullif(btrim(coalesce(p_mutation_domain,'')),'') is null then
      raise exception 'Mutation domain is required for mutating action %',p_action_code;
    end if;

    if coalesce(p_target_version_refs_json,'{}'::jsonb)='{}'::jsonb then
      raise exception 'Target version references are required for mutating action %',p_action_code;
    end if;

    if coalesce(p_rollback_plan_json,'{}'::jsonb)='{}'::jsonb then
      raise exception 'Rollback plan is required for mutating action %',p_action_code;
    end if;
  end if;

  if p_idempotency_key is not null then
    select *
      into v_existing
    from public.feya_growth_execution_requests_v1 e
    where e.idempotency_key=p_idempotency_key
    limit 1;

    if found then
      return query
      select v_existing.execution_request_id,v_existing.request_code,false,
             v_existing.request_status,v_existing.request_hash;
      return;
    end if;
  end if;

  v_status := case
    when v_action.config_json ->> 'approval_class' in ('NONE','NONE_FOR_ANALYSIS') then 'APPROVED'
    when v_action.config_json ->> 'approval_class'='NONE_FOR_DRY_RUN' and v_dry_run then 'APPROVED'
    else 'APPROVAL_REQUIRED'
  end;

  v_code := 'EXE-' || to_char(clock_timestamp(),'YYYYMMDD-HH24MISS') || '-' ||
            upper(substr(replace(gen_random_uuid()::text,'-',''),1,6));

  insert into public.feya_growth_execution_requests_v1 (
    request_code,action_code,action_capability_version,
    action_class,executor_type,approval_class,request_status,
    request_hash,mutation_domain,target_scope_json,target_version_refs_json,
    request_payload_json,rollback_plan_json,postflight_check_json,
    requested_by_type,requested_by_user_id,idempotency_key
  )
  values (
    v_code,p_action_code,v_action.version_no,
    v_action.config_json ->> 'action_class',
    v_action.config_json ->> 'executor_type',
    v_action.config_json ->> 'approval_class',
    v_status,'PENDING',
    nullif(upper(btrim(p_mutation_domain)),''),
    coalesce(p_target_scope_json,'{}'::jsonb),
    coalesce(p_target_version_refs_json,'{}'::jsonb),
    coalesce(p_request_payload_json,'{}'::jsonb),
    coalesce(p_rollback_plan_json,'{}'::jsonb),
    coalesce(p_postflight_check_json,'{}'::jsonb),
    p_requested_by_type,p_requested_by_user_id,p_idempotency_key
  )
  returning * into v_row;

  v_material := public.feya_fn_execution_request_material_json_v1(v_row);
  v_hash := encode(
    extensions.digest(convert_to(v_material::text,'UTF8'),'sha256'),
    'hex'
  );

  update public.feya_growth_execution_requests_v1 e
  set request_hash=v_hash,
      approval_hash=case when v_status='APPROVED' then v_hash else null end,
      approved_at=case when v_status='APPROVED' then now() else null end,
      updated_at=now()
  where e.execution_request_id=v_row.execution_request_id
  returning * into v_row;

  return query
  select v_row.execution_request_id,v_row.request_code,true,
         v_row.request_status,v_row.request_hash;
end;
$function$
